      { q: "बाबा भारती कहाँ रहते थे?", options: ["गाँव से बाहर एक छोटे मंदिर में", "खड्ग सिंह के घर में", "शहर के महल में", "आश्रम में बहुत दूर"], answer: 0, explain: "उन्होंने सब कुछ छोड़कर गाँव से बाहर एक मंदिर में रहना शुरू किया।", level: 1 },
      { q: "खड्ग सिंह घोड़ा देखने क्यों आया था?", options: ["उसे बाबा से लड़ना था", "वह घोड़ा बेचना चाहता था", "उसे इलाज चाहिए था", "उसे घोड़े की प्रशंसा सुनकर देखने की इच्छा हुई"], answer: 3, explain: "सुलतान की कीर्ति सुनकर वह उसे देखने के लिए अधीर हो उठा।", level: 1 },
      { q: "घोड़ा छीनने के बाद खड्ग सिंह ने अंत में क्या किया?", options: ["घोड़ा बेच दिया", "घोड़ा लौटा दिया", "घोड़ा छिपा दिया", "घोड़े को भगा दिया"], answer: 1, explain: "पश्चात्ताप के कारण उसने रात में घोड़ा अस्तबल में बाँध दिया।", level: 1 },
      { q: "'अस्तबल' शब्द का अर्थ क्या है?", options: ["गायों का स्थान", "घोड़े बाँधने का स्थान", "किसान का खेत", "साधु की कुटिया"], answer: 1, explain: "अस्तबल घोड़े बाँधने की जगह को कहते हैं।", level: 1 },
      { q: "'बाबा भारती भी मनुष्य ही थे' – यह कथन किस बात का समर्थन करता है?", options: ["वे बहुत क्रोधी थे", "वे धन के लालची थे", "वे सबसे डरते थे", "वे अपने घोड़े की प्रशंसा दूसरों से सुनने को उत्सुक थे"], answer: 3, explain: "अपनी चीज़ की प्रशंसा सुनने की इच्छा सामान्य मनुष्य में होती है, बाबा में भी थी।", level: 2 },
      { q: "बाबा ने खड्ग सिंह से घटना को गुप्त रखने को क्यों कहा?", options: ["वे चाहते थे कि लोग गरीबों पर विश्वास करना न छोड़ें", "वे खड्ग सिंह से डरते थे", "वे घोड़े को भूलना चाहते थे", "उन्हें अपनी बदनामी का डर था"], answer: 0, explain: "बाबा को चिंता थी कि घटना जानकर लोग असली गरीबों की सहायता करना बंद कर देंगे।", level: 2 },
      { q: "खड्ग सिंह की आँखों में रात को आँसू क्यों थे?", options: ["वह डर गया था", "उसे चोट लगी थी", "उसे अपनी गलती का पश्चात्ताप था", "उसे घोड़ा बेचना पड़ा"], answer: 2, explain: "बाबा के ऊँचे विचारों से उसे अपने कार्य पर पश्चात्ताप हुआ।", level: 2 },
      { q: "'वह डाकू था और जो वस्तु उसे पसंद आ जाए, उस पर वह अपना अधिकार समझता था' – इससे खड्ग सिंह के बारे में क्या पता चलता है?", options: ["वह बहुत गरीब था", "वह घोड़े का पारखी नहीं था", "वह बहुत दयालु था", "वह स्वार्थी और ज़बरदस्ती करने वाला था"], answer: 3, explain: "जो पसंद आए उसे ज़बरदस्ती अपना मान लेना उसके स्वार्थी स्वभाव को दिखाता है।", level: 2 },
      { q: "रेखा ने बाज़ार में एक घायल बुज़ुर्ग को देखकर उसकी सहायता की। बाद में उसे लगा कि वह बुज़ुर्ग धोखेबाज़ निकला। फिर भी वह आगे सहायता करने से नहीं हिचकी। उसका यह निर्णय कहानी के किस विचार से मेल खाता है?", options: ["बाबा भारती का विश्वास बनाए रखने का विचार", "खड्ग सिंह की चालाकी", "घोड़े की चाल का वर्णन", "डाकुओं का भय"], answer: 0, explain: "बाबा भी यही चाहते थे कि धोखा खाकर भी लोग ज़रूरतमंदों पर विश्वास करना न छोड़ें।", level: 2 },
      { q: "कहानी का शीर्षक 'हार की जीत' क्यों उपयुक्त है?", options: ["घोड़ा दौड़ में हार गया", "बाबा ने मैच जीता", "बाबा ने घोड़ा खोकर भी डाकू का हृदय जीत लिया", "डाकू युद्ध हार गया"], answer: 2, explain: "बाबा बाहर से हारे, पर उनके व्यवहार ने खड्ग सिंह का हृदय बदलकर उन्हें जीत दिला दी।", level: 3 },
      { q: "'घोड़ा हवा से बातें करने लगा' का भाव क्या है?", options: ["घोड़ा रुक गया", "घोड़ा बहुत तेज़ दौड़ने लगा", "घोड़ा हिनहिनाने लगा", "घोड़ा थक गया"], answer: 1, explain: "यह मुहावरा बहुत तेज़ गति के लिए प्रयुक्त होता है।", level: 3 },
      { q: "बाबा ने खड्ग सिंह की ओर 'बकरा कसाई की ओर जैसे देखता है' वैसे क्यों देखा?", options: ["वे मज़ाक कर रहे थे", "वे बहुत असहाय और दुखी थे", "वे बहुत खुश थे", "वे डाकू को डाँटना चाहते थे"], answer: 1, explain: "यह उपमा बाबा की विवशता, भय और दुख के भाव को प्रकट करती है।", level: 3 },
      { q: "रवि की साइकिल उसके मित्र ने बिना पूछे उठा ली, पर रवि ने कहा, 'कोई बात नहीं, पर अगली बार पूछकर लेना।' यह कहानी के किस पात्र के गुण से मेल खाता है?", options: ["सुलतान की गति से", "वैद्य की चतुराई से", "बाबा भारती की क्षमा और संयम से", "खड्ग सिंह के बाहुबल से"], answer: 2, explain: "बाबा ने भी चोरी के बाद क्रोध किए बिना शांति से अपनी बात रखी।", level: 3 }
