    written: [
      { q: "'हार की जीत' के लेखक कौन हैं?", a: "इस कहानी के लेखक **सुदर्शन** हैं।", marks: 1 },
      { q: "बाबा भारती के घोड़े का नाम क्या था?", a: "घोड़े का नाम **सुलतान** था।", marks: 1 },
      { q: "खड्ग सिंह ने बाबा भारती से घोड़ा कैसे हथियाया?", a: "1. उसने अपाहिज का वेश बनाया और रास्ते में कराहने लगा।\n2. दयालु बाबा ने उसे घोड़े पर बिठाया, तभी वह घोड़े को लेकर भाग निकला।", marks: 2 },
      { q: "बाबा भारती घोड़े से इतना प्रेम क्यों करते थे? कोई दो बातें लिखिए।", a: "1. घोड़ा सुंदर और बलवान था, उसकी चाल मोर के नाच जैसी थी।\n2. बाबा ने सब कुछ छोड़ दिया था, इसलिए भजन से बचा समय वे घोड़े को देते थे।", marks: 2 },
      { q: "'हृदय पर साँप लोटना' मुहावरे का अर्थ बताइए और कहानी में इसका प्रयोग किस संदर्भ में हुआ है?", a: "1. इसका अर्थ है – दूसरे की वस्तु या सफलता देखकर बहुत जलन या ईर्ष्या होना।\n2. सुलतान की चाल देखकर खड्ग सिंह के हृदय पर साँप लोटने लगा।", marks: 2 },
      { q: "बाबा भारती के चरित्र की तीन विशेषताएँ लिखिए।", a: "1. वे साधु और भगवान के भक्त थे, धन-संपत्ति से दूर थे।\n2. वे दयालु थे – अपाहिज की सहायता के लिए उतर पड़े।\n3. वे समाज के विश्वास की चिंता करने वाले, उदार और ऊँचे विचारों वाले थे।", marks: 3 },
      { q: "कहानी से हमें क्या शिक्षा मिलती है? तीन बिंदुओं में लिखिए।", a: "1. अच्छे विचार और सच्चा व्यवहार बुरे व्यक्ति को भी बदल सकता है।\n2. हमें ज़रूरतमंदों पर विश्वास और दया बनाए रखनी चाहिए।\n3. किसी की वस्तु ज़बरदस्ती या धोखे से लेना गलत है।", marks: 3 },
      { q: "पढ़िए और उत्तर दीजिए – एक दिन बस में गीता का पर्स चोरी हो गया। थोड़ी देर बाद एक लड़का पर्स लौटाकर बोला, 'मुझे माफ़ कर दीजिए।' गीता ने उसे डाँटा नहीं, केवल इतना कहा, 'अब कभी किसी की चीज़ मत चुराना।' लड़का शर्मिंदा होकर चला गया।\n(i) इस प्रसंग की तुलना कहानी के किस प्रसंग से की जा सकती है?\n(ii) गीता के व्यवहार में कौन-सा गुण दिखता है?\n(iii) लड़के में क्या परिवर्तन आया?", a: "(i) इसकी तुलना खड्ग सिंह द्वारा घोड़ा लौटाने और बाबा भारती के शांत व्यवहार से की जा सकती है।\n(ii) गीता के व्यवहार में **क्षमा और संयम** का गुण दिखता है।\n(iii) लड़के को अपनी गलती का एहसास हुआ और उसने पश्चात्ताप करके चीज़ लौटा दी।", marks: 4, type: "case" }
    ]
