      { q: "'किसान' के वेश में कौन था?", options: ["महाराज", "एक खिलाड़ी", "जानकीनाथ", "सरदार सुजान सिंह"], answer: 3, explain: "अंत में पता चलता है कि वह किसान स्वयं सुजान सिंह थे।", level: 2 },
      { q: "नीलम ने विद्यालय से लौटते समय एक बुज़ुर्ग को सामान उठाने में कठिनाई में देखा, तो बिना कहे उनका बैग उठाकर घर तक छोड़ आई। यह व्यवहार किस पात्र के गुण से मेल खाता है?", options: ["जानकीनाथ के", "खिलाड़ियों के", "महाराज के", "उम्मीदवारों के दिखावे के"], answer: 0, explain: "जानकीनाथ ने भी बिना कहे आगे बढ़कर सहायता की थी।", level: 2 },
      { q: "'मगर उन आँखों में सत्कार था, इन आँखों में ईर्ष्या' – किन आँखों में सत्कार था?", options: ["किसान की आँखों में", "उम्मीदवारों की आँखों में, जानकीनाथ के प्रति", "रियासत के कर्मचारियों की आँखों में", "महाराज की आँखों में"], answer: 2, explain: "कर्मचारी और रईस जानकीनाथ का सत्कार कर रहे थे, जबकि असफल उम्मीदवारों में ईर्ष्या थी।", level: 3 },
      { q: "कहानी का नाम 'परीक्षा' क्यों उपयुक्त है?", options: ["उसमें लिखित परीक्षा होती है", "चरित्र और गुणों की जाँच कहानी का केंद्र है", "उसमें विद्यालय का वर्णन है", "उसमें गणित की परीक्षा है"], answer: 1, explain: "पूरी कहानी उम्मीदवारों के चरित्र की परीक्षा के इर्द-गिर्द घूमती है।", level: 3 },
      { q: "कहानी में सुजान सिंह की परीक्षा के तरीके की विशेषता क्या है?", options: ["उन्होंने उम्मीदवारों से प्रश्न पूछे", "उन्होंने वेश बदलकर व्यावहारिक स्थिति में परखा", "उन्होंने सबको पैसे दिए", "उन्होंने अख़बार पढ़ा"], answer: 1, explain: "किसान के वेश में उन्होंने वास्तविक परिस्थिति में उम्मीदवारों के व्यवहार को परखा।", level: 3 },
      { q: "अरुण ने कक्षा-नेता के चुनाव में भाषण तो अच्छे दिए, पर जब किसी साथी को सहायता चाहिए थी तो नज़रअंदाज़ कर दिया। यह कहानी की किस बात का उदाहरण है?", options: ["खेल-भावना का", "मित्रता का", "दिखावे और असली चरित्र के अंतर का", "परिश्रम की जीत का"], answer: 2, explain: "कहानी बताती है कि सच्चा चरित्र ज़रूरत के समय व्यवहार में दिखता है।", level: 3 }
