      { q: "लेखक के अनुसार माँ की ममता और पेड़ के फूलों में क्या समानता है?", options: ["दोनों रंग-बिरंगे होते हैं", "दोनों सूख जाते हैं", "दोनों कठोर होते हैं", "दोनों संतान के प्रति स्नेह से खिलते हैं"], answer: 3, explain: "लेखक ने कहा है कि संतान के प्रति स्नेह से पेड़ पर फूल खिल उठते हैं, जैसे माँ का स्नेह।", level: 2 },
      { q: "खिड़की के पास रखे गमले का पौधा रोशनी की ओर क्यों झुक जाता है?", options: ["उसे प्रकाश चाहिए, इसलिए पत्तियाँ और डालियाँ उसी ओर बढ़ती हैं", "हवा ने उसे झुका दिया", "उसे ठंड लग रही है", "वह थक गया है"], answer: 0, explain: "पौधे प्रकाश की ओर बढ़ते हैं, यह बात पाठ में बताई गई है।", level: 2 },
      { q: "'पेड़ के पत्तों पर सूर्य का प्रकाश पड़ने पर क्या होता है?' – लेखक के अनुसार इसका परिणाम क्या है?", options: ["पत्ते गिर जाते हैं", "पत्ते सूख जाते हैं", "पत्ते सूर्य की ऊर्जा से हवा के हानिकारक अंश को लेकर पेड़ के शरीर के लिए उपयोग करते हैं", "पत्ते रंग बदलते हैं"], answer: 2, explain: "पत्ते सूर्य की ऊर्जा से वायु का अंश लेकर पेड़ को पोषण देते हैं और हवा शुद्ध हो जाती है।", level: 3 },
      { q: "फूल पराग-कण के लिए क्यों आवश्यक हैं?", options: ["पराग से सुगंध बनती है", "पराग से बीज पकता है", "पराग से पत्ते हरे होते हैं", "पराग से जड़ मज़बूत होती है"], answer: 1, explain: "पराग-कण के बिना बीज नहीं पक सकता, इसलिए पराग का ले जाया जाना ज़रूरी है।", level: 3 },
      { q: "लेखक ने 'पेड़ का संतान के लिए सब कुछ लुटाना' बताकर क्या संदेश दिया?", options: ["पेड़ निर्बल होते हैं", "प्रकृति में त्याग और ममता का भाव भरा है", "पेड़ फल बेचते हैं", "पेड़ स्वार्थी होते हैं"], answer: 1, explain: "पेड़ संतान के लिए अपना सब कुछ अर्पित कर देता है, जो माँ जैसी ममता है।", level: 3 },
      { q: "रेहान ने स्कूल की बगिया के हर पौधे के पास रोज़ पानी डाला और खिड़की के पास रखे गमलों को धूप की ओर घुमा दिया। इसमें उसने पाठ की किन बातों का ध्यान रखा?", options: ["पत्ते हवा नहीं लेते", "पौधे बोलते हैं", "जड़ों को रस और पत्तों को प्रकाश की आवश्यकता", "जड़ें ऊपर होती हैं"], answer: 2, explain: "पौधों को जड़ से जल और पत्तों के लिए प्रकाश चाहिए – यह बात पाठ में बताई गई है।", level: 3 }
